mapper.update:
UPDATE tc_model_socket_message
   SET description = #{s.description},
       data_index  = #{s.dataIndex},
       updated_at  = CURRENT_TIMESTAMP
 WHERE model_key = #{s.modelKey}
   AND socket_msg_name = #{s.socketMsgName}

mapper.select:
SELECT 
  FROM tc_model_socket_message
 WHERE model_key = #{modelKey}
   AND socket_msg_name = #{socketMsgName}

SELECT 
  FROM tc_model_socket_message
 WHERE model_key = #{modelKey}
 ORDER BY socket_msg_name ASC, socket_msg_key ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM tc_model_socket_message
 WHERE model_key = #{modelKey}
   AND socket_msg_name = #{socketMsgName}
